<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import TransportMap from './TransportMap.vue'
import rover from '@/assets/transport/rover-side-v2.png'
import {watch} from 'vue'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import {transportState as state,transportRoadStatus,transportRequest,refreshTransport,useTransport,stopName,taskStatus} from '@/api/transport'
const emit=defineEmits<{(e:'close'):void}>()
const tabs=[{id:'fleet',label:'车辆总览'},{id:'tasks',label:'运输任务'},{id:'planning',label:'路线规划'},{id:'roads',label:'道路与避障'},{id:'inventory',label:'仓储交接'},{id:'history',label:'运输历史'}]
const automatic=ref(false)
const tab=ref('fleet'),source=ref('supply'),destination=ref('pear2'),goods=ref('肥料'),quantity=ref(100),unit=ref('kg'),preview=ref<string[]>([]),error=ref(''),notice=ref(''),busy=ref(false),road=ref('supply--junction'),panel=ref<HTMLElement>()
const available=computed(()=>state.value?.inventory.filter(i=>i.location===source.value&&i.available-i.reserved>0)||[])
const active=computed(()=>state.value?.tasks.find(t=>!['COMPLETED','CANCELLED','QUEUED'].includes(t.status)))
const running=computed(()=>state.value?.tasks.filter(t=>!['COMPLETED','CANCELLED'].includes(t.status))||[])
const freeStock=computed(()=>available.value.find(i=>i.goods===goods.value&&i.unit===unit.value))
let release=()=>{}
async function action(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await refreshTransport()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function plan(){await action(async()=>{const data=await transportRequest('/plan?source='+encodeURIComponent(source.value)+'&destination='+encodeURIComponent(destination.value));preview.value=data.route;notice.value='路线校验通过：全车安全包络不进入地块或水域。'})}
async function create(){await action(async()=>{await transportRequest('/tasks','POST',{source:source.value,destination:destination.value,goods:goods.value,quantity:quantity.value,unit:unit.value,automatic:automatic.value});notice.value='任务已保存并预留货物，等待车辆调度。';tab.value='tasks'})}
async function control(id:string,cmd:string){await action(()=>transportRequest('/tasks/'+id+'/control','POST',{action:cmd}))}
const labels:Record<string,string>={RESERVE:'预留',RELEASE:'释放预留',OUTBOUND:'装货出库',INBOUND:'卸货入库'}
function key(e:KeyboardEvent){if(e.key==='Escape'){emit('close');return}if(e.key!=='Tab')return;const list=Array.from(panel.value?.querySelectorAll<HTMLElement>('button:not([disabled]),select,input')||[]).filter(n=>n.offsetParent!==null);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}
watch([source,destination],()=>{preview.value=[];notice.value=''})
watch(source,()=>{const choices=available.value;if(!choices.some(i=>i.goods===goods.value&&i.unit===unit.value)){goods.value=choices[0]?.goods||'';unit.value=choices[0]?.unit||'kg'}const stock=freeStock.value;if(stock)quantity.value=Math.min(quantity.value,stock.available-stock.reserved,500)})
const previous=document.activeElement as HTMLElement|null
onMounted(()=>{release=useTransport();panel.value?.focus()});onBeforeUnmount(()=>{release();if(previous?.isConnected)previous.focus()})
</script>
<template><Teleport to="body"><div class="risk-backdrop" @click.self="emit('close')"><section ref="panel" class="risk-center" role="dialog" aria-modal="true" aria-label="自动导航运输中心" tabindex="-1" @keydown="key"><header><div><small>盐田丰语 · 道路限定运输</small><h1>自动导航运输中心 <span>软件仿真</span></h1></div><button aria-label="关闭运输中心" @click="emit('close')"><AgentIcon name="close" :size="20"/></button></header><div class="risk-layout"><aside><div class="risk-brand"><AgentIcon name="grid" :size="23"/><span>连接地块与仓储<small>任务 · 道路 · 交接</small></span></div><nav aria-label="运输中心页面"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id">{{t.label}}<span>›</span></button></nav><div class="sidebar-foot">田地和水域禁止驶入<br/>路段不通时停车等待</div></aside><main><div class="risk-heading"><div><small>{{tabs.find(t=>t.id===tab)?.label}}</small><h2>自动运输车 01</h2></div><button class="emergency" :disabled="busy" @click="control('cart-01',state?.emergency?'RELEASE_STOP':'STOP')">{{state?.emergency?'解除急停':'紧急停止'}}</button></div><p v-if="error" role="alert" class="risk-error">{{error}}</p><p v-if="notice" role="status" class="risk-notice">{{notice}}</p><template v-if="state"><template v-if="tab==='fleet'"><div class="risk-stats"><div><small>车辆状态</small><strong class="small-value">{{state.emergency?'已急停':active?taskStatus[active.status]:'空闲'}}</strong><span>{{active?.notice||'等待运输任务'}}</span></div><div><small>模拟电量</small><strong>{{state.battery.toFixed(0)}}<em>%</em></strong></div><div><small>任务队列</small><strong>{{running.length}}<em>单</em></strong></div><div><small>批准道路</small><strong>{{transportRoadStatus.filter(r=>r.legal).length}}<em>段</em></strong></div></div><section class="risk-card"><div class="rover-summary"><img :src="rover" alt="自动运输车斜侧视图"/><div><small>自主运输 · 地块与仓储之间</small><h3>沿路运输，每一次交接都有记录</h3><p>装载、运输、卸货、回仓，查看完整任务进度。</p></div></div><button class="secondary" :disabled="busy||running.length>0||state.emergency" @click="control('cart-01','DEMO_DRIVE')">演示行驶与转向（不搬货）</button><p class="caption">沿批准道路经过果园与仓库，再返回充电点。关闭面板可观看实景／3D中的小车运动。</p><TransportMap overview/><button class="primary" @click="tab='planning'">规划新的运输任务</button><button class="secondary" :disabled="busy||state.emergency" @click="action(()=>transportRequest('/tasks','POST',{source:'pear2',destination:'warehouse',goods:'鸭梨',quantity:50,unit:'kg',automatic:true}))">试运行：鸭梨回仓 50 kg</button><button class="secondary" :disabled="busy||running.length>0||state.emergency" @click="control('cart-01','RETURN_CHARGE')">空载返回充电点</button></section></template>
<template v-else-if="tab==='planning'"><div class="risk-columns"><section class="risk-card"><h3>取送货规划</h3><label>取货点<select v-model="source" aria-label="运输取货点" @change="preview=[]"><option v-for="s in state.stops.filter(s=>['supply','warehouse','pear1','pear2','pear3','wheat','jujube','vegetable'].includes(s.id))" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>交付点<select v-model="destination" aria-label="运输交付点" @change="preview=[]"><option v-for="s in state.stops.filter(s=>['supply','warehouse','pear1','pear2','pear3','wheat','jujube','vegetable'].includes(s.id))" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>运输货物<select v-model="goods" aria-label="运输货物" @change="unit=goods==='农具'?'件':'kg'"><option v-for="i in available" :key="i.goods" :value="i.goods">{{i.goods}}</option><option v-if="!available.length" value="">暂无可用库存</option></select></label><div class="form-pair"><label>数量<input v-model.number="quantity" aria-label="运输数量" type="number" min="1" max="500"/></label><label>单位<select v-model="unit"><option>kg</option><option>件</option></select></label></div><p class="caption">源库存可用：{{freeStock?freeStock.available-freeStock.reserved:0}} {{unit}}。载荷暂按登记数量上限 500 校验，工具不折算重量。</p><label class="automatic-check"><input v-model="automatic" type="checkbox"/>自动确认装卸（软件仿真）</label><button class="secondary" :disabled="busy" @click="plan">预览合法路线</button><button class="primary" :disabled="busy||!freeStock||quantity<=0||quantity>500||quantity>freeStock.available-freeStock.reserved||source===destination||state.emergency" @click="create">保存并调度运输</button></section><section class="risk-card"><h3>批准道路上的规划结果</h3><TransportMap overview :preview="preview"/><p class="caption">只允许沿批准道路行驶。各地块在道路边缘交接，路线不进入种植区。</p></section></div></template>
<template v-else-if="tab==='tasks'"><section class="risk-card"><h3>当前运输任务</h3><article v-for="t in running" :key="t.id" class="history-row"><div class="task-heading"><strong>{{t.goods}} · {{t.quantity}} {{t.unit}}</strong><span>{{taskStatus[t.status]}}</span></div><p>{{stopName(t.source)}} → {{stopName(t.destination)}}</p><small>{{t.notice}} · {{t.loaded?'货物在途':'尚未装货'}} · {{t.automatic?'自动交接':'人工确认'}}</small><div class="task-actions"><button v-if="t.status==='RUNNING'" :disabled="busy" @click="control(t.id,'PAUSE')">暂停</button><button v-if="t.status==='PAUSED'" :disabled="busy||state.emergency" @click="control(t.id,'RESUME')">继续</button><button v-if="['QUEUED','WAIT_LOAD'].includes(t.status)" :disabled="busy" @click="control(t.id,'CANCEL')">取消任务</button><button v-if="t.status==='WAIT_LOAD'" :disabled="busy" @click="control(t.id,'LOAD')">确认装货</button><button v-if="t.status==='WAIT_UNLOAD'" :disabled="busy" @click="control(t.id,'UNLOAD')">确认卸货入库</button></div></article><p v-if="!running.length" class="empty">暂无任务，先规划取货与交付点。</p></section></template>
<template v-else-if="tab==='roads'"><div class="risk-columns"><section class="risk-card"><h3>道路开放与禁行</h3><article v-for="r in state.roads" :key="r.id" class="road-row"><div><strong>{{stopName(r.a)}} → {{stopName(r.b)}}</strong><small>{{transportRoadStatus.find(v=>v.id===r.id)?.legal?'车身校验通过':'包络未通过 · 禁止通行'}}</small></div><button :disabled="busy" @click="action(()=>transportRequest('/roads/'+r.id,'POST',{blocked:!r.blocked}))">{{r.blocked?'解除封路':'封闭'}}</button></article></section><section class="risk-card"><h3>障碍仿真</h3><TransportMap overview/><label>障碍所在路段<select v-model="road"><option v-for="r in state.roads" :key="r.id" :value="r.id">{{stopName(r.a)}} → {{stopName(r.b)}}</option></select></label><button class="secondary" :disabled="busy" @click="action(()=>transportRequest('/obstacles','POST',{road,moving:false}))">放置道路障碍</button><button class="secondary" :disabled="busy" @click="action(()=>transportRequest('/obstacles','POST',{road,moving:true}))">模拟横穿道路的行人</button><button class="text-button" :disabled="busy" @click="action(()=>transportRequest('/obstacles','DELETE'))">清除障碍，允许重新规划 →</button><p class="caption">使用 DWA 速度与角速度采样，预测车身包络碰撞；道路过窄时停车，不越界绕障。当前为单车，队列依次调度。</p></section></div></template>
<template v-else-if="tab==='inventory'"><section class="risk-card"><h3>仓储与在途库存</h3><div class="stock-grid"><article v-for="i in state.inventory" :key="i.location+i.goods"><small>{{stopName(i.location)}}</small><strong>{{i.goods}}</strong><b>{{i.available-i.reserved}} {{i.unit}}</b><span>可用 · 已预留 {{i.reserved}} {{i.unit}}</span></article></div><h3 class="ledger-title">交接流水</h3><article v-for="entry in [...state.ledger].reverse().slice(0,20)" :key="entry.id" class="history-row"><strong>{{labels[entry.type]}} · {{entry.goods}} {{entry.quantity}} {{entry.unit}}</strong><p>{{stopName(entry.location)}} · 任务 {{entry.taskId.slice(0,8)}}</p><time>{{entry.time}}</time></article><p class="caption">装货确认扣源库存；卸货确认增加目标库存。未确认交接不会自动入库。</p></section></template>
<template v-else><section class="risk-card"><h3>运输与交付记录</h3><article v-for="t in [...state.tasks].reverse()" :key="t.id" class="history-row"><strong>{{t.goods}} · {{t.quantity}} {{t.unit}} · {{taskStatus[t.status]}}</strong><p>{{stopName(t.source)}} → {{stopName(t.destination)}}</p><time>{{t.createdAt}}</time><small>{{t.completedAt?'交付时间 '+t.completedAt:'尚未交付'}}</small></article><p v-if="!state.tasks.length" class="empty">暂无运输记录</p></section></template><p class="rule-note">{{state.algorithm}}。当前仅单车软件仿真，概念地图未经 GIS 实测标定。</p></template></main></div></section></div></Teleport></template>
<style scoped>

.risk-backdrop{position:fixed;inset:0;z-index:140;background:#0e1b29aa;backdrop-filter:blur(12px);display:grid;place-items:center;padding:24px}.risk-center{width:min(1200px,100%);height:min(860px,92vh);background:var(--ui-subtle);color:var(--ui-ink);border:1px solid #fff8;border-radius:22px;box-shadow:0 30px 100px #0005;display:flex;flex-direction:column;overflow:hidden;font-family:var(--font-sans);animation:appear .25s ease}button,select,input{font:inherit}button{cursor:pointer;color:inherit}button:disabled{opacity:.5;cursor:wait}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--ui-brand);outline-offset:3px}header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;border-bottom:1px solid var(--ui-brand-soft)}header small{font-size:10px;color:#8b999f}h1{font-size:22px;margin:6px 0 0;font-weight:650}h1 span{font-size:10px;font-weight:400;color:var(--ui-brand);background:var(--ui-brand-soft);padding:5px 8px;border-radius:6px;margin-left:8px}header>button{display:grid;place-items:center;width:34px;height:34px;border:0;border-radius:9px;background:var(--ui-brand-soft)}.risk-layout{display:grid;grid-template-columns:210px minmax(0,1fr);flex:1;min-height:0}aside{padding:24px 15px;border-right:1px solid var(--ui-brand-soft);display:flex;flex-direction:column;background:#f5f9f6}.risk-brand{display:flex;gap:10px;align-items:center;color:var(--ui-brand);padding:0 8px 24px;font-size:12px}.risk-brand small{display:block;color:#95a49b;font-size:10px;margin-top:5px}nav{display:grid;gap:7px}nav button{display:flex;align-items:center;gap:11px;width:100%;padding:13px 12px;border:0;border-radius:10px;background:transparent;text-align:left;font-size:12px;color:#73887d;transition:.2s}nav button span{margin-left:auto}nav button:hover{background:var(--ui-brand-soft)}nav button.active{background:var(--ui-brand);color:white;box-shadow:0 5px 15px #28664820}.sidebar-foot{margin-top:auto;font-size:10px;line-height:1.9;color:#a0a