lor:#92a296;margin-top:6px}.risk-row>span{font-size:10px;color:#aa8355;white-space:nowrap}.text-button{border:0;background:none;color:var(--ui-brand);font-size:11px;padding:16px 0 0}.primary,.secondary{display:block;width:100%;border:0;border-radius:9px;background:var(--ui-brand);color:white;padding:12px;font-size:12px;margin-top:18px}.secondary{background:var(--ui-brand-soft);color:var(--ui-brand);margin-top:10px}.detail-banner{display:flex;align-items:center;justify-content:space-between;padding:24px;border-radius:14px;border:1px solid var(--ui-brand-soft);background:linear-gradient(120deg,#edf5ef,white);margin-bottom:20px}.detail-banner small{font-size:11px;color:#7b9686}.detail-banner h3{font-size:23px;font-weight:600;margin:9px 0}.detail-banner p{font-size:11px;color:#92a296;margin:0}.score-ring{width:90px;height:90px;border:7px solid #e7d6b7;border-top-color:#b69a60;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column;flex-shrink:0}.score-ring strong{font-size:29px}.score-ring small{font-size:10px;color:#ad875b}.observation-cards{display:grid;gap:10px}.observation-cards article{background:#f4f8f5;border-radius:10px;padding:14px}.observation-cards small{font-size:10px;color:#91a499}.observation-cards strong{display:block;font-size:13px;font-weight:550;margin:7px 0;overflow-wrap:anywhere}.observation-cards p{font-size:10px;color:#91a499;line-height:1.9;margin:0}.steps{padding-left:20px;font-size:12px;color:#6e8878;line-height:2.8}.chain{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:25px 0}.chain span{padding:12px;background:var(--ui-brand-soft);border-radius:8px;font-size:11px;color:var(--ui-brand)}.chain b{color:#90ad9b}.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.recommended{border-color:#87ae94;background:#f4faf6}.plan-score{display:block;font-size:38px;color:var(--ui-brand);margin:20px 0}.plan-grid label{display:flex;align-items:center;gap:6px;font-size:10px;color:#698874;mar